(()=>{'use strict';const $=s=>document.querySelector(s),form=$('#cargo-form'),engine=window.CargoEngine,methods=engine.methods,fmt=(n,d=2)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d}),usd=n=>fmt(n)+' USD';let inputMode='total',boxId=0,last=null,methodKey='auto';const menu=$('#menu'),nav=$('#nav');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));nav.classList.toggle('open',!expanded)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
function addBox(){if($('#box-rows').children.length>=20)return;const id=++boxId,row=document.createElement('div');row.className='box-row';row.dataset.box=id;row.innerHTML='<div class="box-row-title"><b>Тип коробки '+id+'</b><button type="button" aria-label="Удалить тип коробки '+id+'">Удалить ×</button></div><div class="box-fields-grid">'+[['qty','Кол-во, шт.','2','1','1'],['length','Длина, см','50','0.1','0.1'],['width','Ширина, см','50','0.1','0.1'],['height','Высота, см','50','0.1','0.1'],['weight','Вес одной, кг','10','0.1','0.1']].map(([key,label,val,min,step])=>'<label for="box-'+id+'-'+key+'">'+label+'<input id="box-'+id+'-'+key+'" data-key="'+key+'" type="number" value="'+val+'" min="'+min+'" max="100000" step="'+step+'" inputmode="decimal" disabled required></label>').join('')+'</div>';$('#box-rows').append(row);row.querySelector('button').addEventListener('click',()=>{row.remove();syncFields();update()});syncFields();update()}
function syncFields(){document.querySelectorAll('#box-rows input').forEach(i=>i.disabled=inputMode!=='boxes');$('#weight').disabled=inputMode!=='total';$('#volume').disabled=inputMode!=='total';$('#add-box').disabled=$('#box-rows').children.length>=20;document.querySelectorAll('.box-row-title button').forEach(b=>b.disabled=$('#box-rows').children.length<=1)}
function readCargo(){if(inputMode==='total')return {weight:Number($('#weight').value),volume:Number($('#volume').value)};return engine.boxes([...document.querySelectorAll('.box-row')].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(el=>[el.dataset.key,Number(el.value)]))))}
function originName(){return $('#origin').value==='Другой город'?$('#origin-custom').value.trim():$('#origin').value}function inputParams(){return {...readCargo(),rate:Number($('#rate').value),factor:Number($('#density-factor').value),min:Number($('#min-weight').value),extras:Number($('#extra-cost').value),fx:Number($('#fx-rate').value),insurance:$('#insurance').checked,value:Number($('#cargo-value').value),insuranceRate:Number($('#insurance-rate').value)}}
function update(){try{if(!form.checkValidity())throw new Error('Проверьте обязательные поля');const p=inputParams(),r=engine.calculate(p),m=methods[methodKey];last={p,r,m};$('#cargo-error').hidden=true;$('#cargo-request').disabled=false;$('#cargo-price').textContent=fmt(r.total);$('#metric-weight').textContent=fmt(r.weight)+' кг';$('#metric-volume').textContent=fmt(r.volume,4)+' м³';$('#metric-density').textContent=fmt(r.density,1)+' кг/м³';$('#billable-weight').textContent=fmt(r.billable)+' кг';$('#volumetric-weight').textContent=fmt(r.volumetric)+' кг';$('#result-rate').textContent=usd(p.rate);$('#freight-cost').textContent=usd(r.freight);$('#result-extras').textContent=usd(r.extras);$('#result-origin').textContent=originName();$('#result-destination').textContent=$('#destination').value.trim()||'Ваш город';$('#result-mode').textContent=m.name+' · ориентир '+m.days+' дн.';$('#cargo-rub').textContent=r.rub!==null?'≈ '+fmt(r.rub)+' ₽ по введённому курсу':'Для суммы в ₽ введите согласованный курс';$('#insurance-line').hidden=!p.insurance;$('#insurance-cost').textContent=r.insurance>0?usd(r.insurance):'По запросу';$('#weight-explanation').textContent=r.basis==='minimum'?'Применён минимум к оплате: '+fmt(p.min)+' кг.':r.basis==='volume'?'Расчёт по объёмному весу: '+fmt(r.volume,4)+' м³ × '+fmt(p.factor)+' кг/м³.':'Расчёт по фактическому весу груза.';$('#comparison-grid').replaceChildren(...Object.entries(methods).map(([key,m])=>{const c=engine.calculate({weight:r.weight,volume:r.volume,rate:m.rate,factor:m.factor,min:m.min});const b=document.createElement('button');b.type='button';b.className='compare-method'+(key===methodKey?' selected':'');b.setAttribute('aria-pressed',String(key===methodKey));b.innerHTML='<span class="compare-method-head"><b>'+m.name+'</b><i>'+(key===methodKey?'✓':'↗')+'</i></span><strong>'+fmt(c.total)+' <small>USD</small></strong><span>'+m.days+' дн. · '+fmt(c.billable)+' кг к оплате</span><small>База '+fmt(m.rate)+' USD/кг</small>';b.addEventListener('click',()=>{const radio=form.querySelector('[name="transport"][value="'+key+'"]');radio.checked=true;chooseMethod(key)});return b}));$('#cargo-message').hidden=true}catch(error){last=null;$('#cargo-error').hidden=false;$('#cargo-request').disabled=true;$('#cargo-price').textContent='—';$('#cargo-rub').textContent='Проверьте параметры груза';$('#weight-explanation').textContent='Заполните корректные параметры для расчёта.';['#metric-weight','#metric-volume','#metric-density','#billable-weight','#volumetric-weight','#freight-cost','#result-rate','#result-extras'].forEach(s=>$(s).textContent='—');$('#comparison-grid').replaceChildren();$('#cargo-message').hidden=true}}
function chooseMethod(key){methodKey=key;const m=methods[key];$('#rate').value=m.rate;$('#density-factor').value=m.factor;$('#min-weight').value=m.min;update()}
document.querySelectorAll('[data-input-mode]').forEach(b=>b.addEventListener('click',()=>{inputMode=b.dataset.inputMode;document.querySelectorAll('[data-input-mode]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));$('#total-fields').hidden=inputMode!=='total';$('#box-fields').hidden=inputMode!=='boxes';syncFields();update()}));$('#add-box').addEventListener('click',addBox);form.querySelectorAll('[name="transport"]').forEach(r=>r.addEventListener('change',()=>chooseMethod(r.value)));$('#origin').addEventListener('change',()=>{const custom=$('#origin').value==='Другой город';$('#origin-custom-label').hidden=!custom;$('#origin-custom').disabled=!custom;update()});form.addEventListener('input',update);form.addEventListener('change',update);form.addEventListener('submit',e=>e.preventDefault());$('#cargo-request').addEventListener('click',()=>{if(!last||!form.reportValidity())return;const {p,r,m}=last;const flags=[['#battery','аккумуляторы'],['#liquid','жидкости / порошки'],['#fragile','хрупкий груз'],['#photo','фото / видео'],['#consolidate','консолидация'],['#buyout','выкуп'],['#door','до адреса'],['#documents','документы для бизнеса'],['#insurance','страхование']].filter(([s])=>$(s).checked).map(([,t])=>t);const boxes=inputMode==='boxes'?[...document.querySelectorAll('.box-row')].map((row,i)=>{const v=Object.fromEntries([...row.querySelectorAll('input')].map(el=>[el.dataset.key,el.value]));return 'Коробки '+(i+1)+': '+v.qty+' шт. × '+v.length+'×'+v.width+'×'+v.height+' см; '+v.weight+' кг/шт.'}).join('\n'):'';const text=['Здравствуйте! Нужен точный расчёт доставки из Китая.','Маршрут: '+originName()+' → '+$('#destination').value,'Товар: '+$('#category option:checked').textContent+($('#cargo-description').value?' / '+$('#cargo-description').value:''),'Вес: '+fmt(r.weight)+' кг. Объём: '+fmt(r.volume,4)+' м³. Плотность: '+fmt(r.density,1)+' кг/м³.',boxes,'Способ: '+m.name+'. Расчётный вес: '+fmt(r.billable)+' кг.','Предварительная оценка: '+usd(r.total)+(r.rub!==null?' / '+fmt(r.rub)+' ₽':''),'Параметры оценки: '+fmt(p.rate)+' USD/кг; коэффициент '+fmt(p.factor)+' кг/м³; минимум '+fmt(p.min)+' кг.','Доп. расходы в оценке: '+usd(r.extras)+'. Страхование: '+(p.insurance?r.insurance>0?usd(r.insurance):'прошу рассчитать':'не выбрано')+'.','Упаковка: '+$('#packing').value,flags.length?'Особенности и услуги: '+flags.join(', '):'','Прошу подтвердить актуальную ставку, полный состав расходов, срок и документы.'].filter(Boolean).join('\n');window.FenekAnalytics?.goal('cargo_calculate',{transport:methodKey,page:location.pathname});window.FenekLeads.open({service:'Карго из Китая',kind:'cargo',source:'cargo_calculator',context:text});});$('#cargo-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#cargo-prepared').value);$('#cargo-copy').textContent='Скопировано ✓'}catch{$('#cargo-prepared').focus();$('#cargo-prepared').select();$('#cargo-copy').textContent='Нажмите Ctrl+C'}});addBox();update();})();
